package common

import("bytes";"encoding/json";"fmt";"net/http")
type TwitchAdapter struct{Token,ClientID,BroadcasterID,SenderID string;Client *http.Client}
func(a TwitchAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){event:=payload;if nested,ok:=payload["event"].(map[string]any);ok{event=nested};user:=fmt.Sprint(event["chatter_user_id"]);if user=="<nil>"||user==""{user=fmt.Sprint(event["user_id"])};text:=fmt.Sprint(event["message"]);if message,ok:=event["message"].(map[string]any);ok{text=fmt.Sprint(message["text"])};if user=="<nil>"||text=="<nil>"{return InboundEvent{},fmt.Errorf("Twitch event has no chat message")};return InboundEvent{Platform:"twitch",UserID:user,ContentType:"text",Text:text,ReplyToID:fmt.Sprint(event["message_id"])},nil}
func(a TwitchAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{if message.Type!="text"{return fmt.Errorf("Twitch chat supports text replies only")};body:=map[string]any{"broadcaster_id":a.BroadcasterID,"sender_id":a.SenderID,"message":message.Text};if event.ReplyToID!=""{body["reply_parent_message_id"]=event.ReplyToID};data,_:=json.Marshal(body);req,_:=http.NewRequest(http.MethodPost,"https://api.twitch.tv/helix/chat/messages",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Client-Id",a.ClientID);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Twitch API returned %s",resp.Status)}};return nil}
